<template><div class="card-body"><el-form label-position="top"><div class="form-grid"><el-form-item label="试卷名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="课程"><el-select v-model="form.course" style="width:100%"><el-option v-for="c in store.courses" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="考试时间"><el-input-number v-model="form.duration" :min="1"/> 分钟</el-form-item><el-form-item label="目标总分"><el-input-number v-model="form.target_score" :min="1"/></el-form-item></div><h3>题型配置</h3><div v-for="(r,i) in form.type_config" :key="i" class="rule-row"><el-select v-model="r.type"><el-option v-for="x in types" :key="x.value" :label="x.label" :value="x.value"/></el-select><span>数量</span><el-input-number v-model="r.count" :min="1"/><span>每题分值</span><el-input-number v-model="r.score_each" :min=".5" :step=".5"/><el-button link type="danger" @click="form.type_config.splice(i,1)">删除</el-button></div><el-button @click="form.type_config.push({type:'single_choice',count:5,score_each:2})"><Plus/>添加题型</el-button><h3>难度比例</h3><div class="ratio"><label>简单 <el-input-number v-model="form.difficulty_ratio.简单" :min="0" :max="1" :step=".1"/></label><label>中等 <el-input-number v-model="form.difficulty_ratio.中等" :min="0" :max="1" :step=".1"/></label><label>困难 <el-input-number v-model="form.difficulty_ratio.困难" :min="0" :max="1" :step=".1"/></label><b>合计 {{(ratioTotal*100).toFixed(0)}}%</b></div><el-checkbox v-model="form.prefer_unused">优先选择未使用题目</el-checkbox><el-checkbox v-model="form.allow_similar">允许相似题</el-checkbox><el-checkbox v-model="form.allow_ai_fill">题库不足时允许AI补题</el-checkbox><div><el-button type="primary" :loading="saving" style="margin-top:20px" @click="submit">按照规则组卷</el-button></div></el-form></div></template><script setup>import{reactive,ref,computed,onMounted}from'vue';import{useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{papersApi}from'../../../api';import{useAppStore}from'../../../stores/app';const router=useRouter(),store=useAppStore(),saving=ref(false),types=[['single_choice','单项选择题'],['multiple_choice','多项选择题'],['judge','判断题'],['fill_blank','填空题'],['short_answer','简答题'],['programming','编程题']].map(([value,label])=>({value,label})),form=reactive({name:'',course:'',paper_type:'规则组卷',duration:90,target_score:100,type_config:[{type:'single_choice',count:20,score_each:2},{type:'judge',count:10,score_each:1},{type:'short_answer',count:5,score_each:6}],difficulty_ratio:{简单:.3,中等:.5,困难:.2},prefer_unused:true,allow_similar:false,allow_ai_fill:false}),ratioTotal=computed(()=>Object.values(form.difficulty_ratio).reduce((a,b)=>a+Number(b),0));const submit=async()=>{if(!form.name||!form.course)return ElMessage.warning('请填写试卷名称并选择课程');if(Math.abs(ratioTotal.value-1)>.001)return ElMessage.warning('难度比例之和必须为100%');saving.value=true;try{const d=await papersApi.rule(form);if(d.shortages.length)await ElMessageBox.alert(d.shortages.map(x=>`${x.type}需要${x.required}道，当前只有${x.available}道，缺少${x.missing}道`).join('\n'),'题库数量不足',{type:'warning'});router.push(`/papers/${d.paper.id}/edit`)}finally{saving.value=false}};onMounted(async()=>{await store.loadCourses();form.course=store.courses[0]?.id||''})</script><style scoped>.rule-row{display:grid;grid-template-columns:180px 45px 130px 75px 130px 50px;gap:10px;align-items:center;margin:10px 0}.ratio{display:flex;gap:20px;align-items:center;margin:12px 0 20px}.ratio label{display:flex;align-items:center;gap:8px}</style>
